-- =====================================================================
-- Waterdrop — customer accounts (Home / Store / Company), branches,
-- family & team members, supplier search with approval, combined bills.
--
-- GENERATED by scripts/gen-migration-12.py (do not edit by hand).
--
-- A "branch" is an existing customers row (stock, orders, deliveries and
-- billing already work per row). A customer account groups branches and
-- members. Roles: owner (everything), admin (everything but the owner),
-- member (order, confirm deliveries, record usage — no bills/payments).
-- Branches of one account served by the same supplier bill to a head
-- branch, so the account gets one combined bill per supplier.
-- =====================================================================

create type public.customer_account_type as enum ('home', 'store', 'company');
create type public.account_member_role as enum ('owner', 'admin', 'member');

create table public.customer_accounts (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 120),
  account_type public.customer_account_type not null default 'home',
  owner_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);
create index customer_accounts_owner_idx on public.customer_accounts (owner_id);

create table public.customer_account_members (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.customer_accounts (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role public.account_member_role not null default 'member',
  status text not null default 'active' check (status in ('active', 'blocked')),
  all_branches boolean not null default true,
  blocked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint customer_account_members_uq unique (account_id, user_id)
);
create index customer_account_members_user_idx on public.customer_account_members (user_id);

create table public.customer_member_branches (
  member_id uuid not null references public.customer_account_members (id) on delete cascade,
  customer_id uuid not null references public.customers (id) on delete cascade,
  primary key (member_id, customer_id)
);

create table public.customer_member_invites (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.customer_accounts (id) on delete cascade,
  code text not null unique check (code ~ '^[A-Z0-9]{8}$'),
  role public.account_member_role not null check (role <> 'owner'),
  all_branches boolean not null default true,
  branch_ids uuid[] not null default '{}',
  label text check (label is null or char_length(label) <= 80),
  expires_at timestamptz not null default now() + interval '7 days',
  used_by uuid references public.profiles (id),
  used_at timestamptz,
  revoked_at timestamptz,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);
create index customer_member_invites_account_idx on public.customer_member_invites (account_id);

alter table public.customers
  add column account_id uuid references public.customer_accounts (id) on delete set null,
  add column branch_name text check (branch_name is null or char_length(branch_name) between 1 and 80),
  add column bill_to_customer_id uuid references public.customers (id) on delete set null;
create index customers_account_idx on public.customers (account_id);
create index customers_bill_to_idx on public.customers (bill_to_customer_id) where bill_to_customer_id is not null;
-- An account may have several branches with the same supplier.
drop index if exists public.customers_user_supplier_uq;

alter table public.suppliers add column listed boolean not null default true;

create table public.supplier_connection_requests (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.customer_accounts (id) on delete cascade,
  supplier_id uuid not null references public.suppliers (id) on delete cascade,
  branch_name text check (branch_name is null or char_length(branch_name) between 1 and 80),
  contact_name text not null check (char_length(contact_name) between 2 and 120),
  phone text check (phone is null or phone ~ '^\+?[0-9 ]{7,16}$'),
  address text not null check (char_length(address) between 3 and 500),
  delivery_instructions text check (delivery_instructions is null or char_length(delivery_instructions) <= 500),
  household_type text check (household_type in ('single', 'couple', 'family', 'shared_room', 'office', 'shop', 'other')),
  members_count integer check (members_count between 1 and 500),
  opening_stock integer check (opening_stock between 0 and 1000),
  daily_consumption integer not null default 0 check (daily_consumption between 0 and 1000),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  reason text check (reason is null or char_length(reason) <= 300),
  customer_id uuid references public.customers (id) on delete set null,
  requested_by uuid references public.profiles (id),
  decided_by uuid references public.profiles (id),
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index supplier_connection_requests_supplier_idx on public.supplier_connection_requests (supplier_id, status);
create unique index supplier_connection_requests_pending_uq
  on public.supplier_connection_requests (account_id, supplier_id, lower(address)) where status = 'pending';

-- ---------------------------------------------------------------------
-- Backfill: one account per existing app customer; they become owner.
-- ---------------------------------------------------------------------
insert into public.customer_accounts (name, account_type, owner_id, created_at)
select (array_agg(c.customer_name order by c.created_at))[1],
       case when bool_or(c.household_type = 'shop') then 'store'::public.customer_account_type
            when bool_or(c.household_type = 'office') then 'company'::public.customer_account_type
            else 'home'::public.customer_account_type end,
       c.user_id, min(c.created_at)
from public.customers c
where c.user_id is not null
group by c.user_id;

update public.customers c set account_id = a.id
from public.customer_accounts a where a.owner_id = c.user_id and c.account_id is null;

insert into public.customer_account_members (account_id, user_id, role, created_at)
select id, owner_id, 'owner', created_at from public.customer_accounts
on conflict (account_id, user_id) do nothing;

-- ---------------------------------------------------------------------
-- Access helpers
-- ---------------------------------------------------------------------
create or replace function public.head_customer_id(p_customer_id uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select coalesce(bill_to_customer_id, id) from public.customers where id = p_customer_id;
$$;

-- The head branch plus every branch that bills to it.
create or replace function public.billing_group(p_head uuid) returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from public.customers where id = p_head or bill_to_customer_id = p_head;
$$;

create or replace function public.my_customer_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select c.id from public.customers c
  where c.account_id is null and c.user_id = auth.uid()
  union
  select c.id from public.customers c
  join public.customer_account_members m on m.account_id = c.account_id
  where m.user_id = auth.uid() and m.status = 'active'
    and (m.all_branches or m.role in ('owner', 'admin')
         or exists (select 1 from public.customer_member_branches b where b.member_id = m.id and b.customer_id = c.id));
$$;

-- Branches whose bills and payments the caller may see (owner / admin).
create or replace function public.my_billing_customer_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select c.id from public.customers c
  where c.account_id is null and c.user_id = auth.uid()
  union
  select c.id from public.customers c
  join public.customer_account_members m on m.account_id = c.account_id
  where m.user_id = auth.uid() and m.status = 'active' and m.role in ('owner', 'admin');
$$;

create or replace function public.my_account_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select account_id from public.customer_account_members where user_id = auth.uid() and status = 'active';
$$;

create or replace function public.my_account_role(p_account_id uuid) returns text
language sql stable security definer set search_path = public as $$
  select role::text from public.customer_account_members
  where account_id = p_account_id and user_id = auth.uid() and status = 'active';
$$;

create or replace function public.require_account_admin(p_account_id uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.require_auth();
  if coalesce(public.my_account_role(p_account_id), '') not in ('owner', 'admin') then
    raise exception 'Only the account owner or an admin can do this' using errcode = '42501';
  end if;
end $$;

-- Owner/admin only: money actions on a branch (resolved by the caller to the head branch).
create or replace function public.customer_for_billing(p_customer_id uuid) returns public.customers
language plpgsql stable security definer set search_path = public as $$
declare
  c public.customers;
begin
  perform public.require_auth();
  select * into c from public.customers where id = p_customer_id;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if c.id not in (select public.my_billing_customer_ids()) then
    raise exception 'Only the account owner or an admin can handle bills and payments' using errcode = '42501';
  end if;
  if c.blocked_at is not null then
    raise exception 'This account has been blocked by your supplier. Please contact them.' using errcode = '42501';
  end if;
  return c;
end $$;

-- Sends a notification to every active member with access to the branch
-- ('billing' audience: owner and admins only). Returns one inserted id.
create or replace function public.notify_customer(
  p_customer_id uuid, p_audience text, p_type text, p_severity text, p_title text, p_message text,
  p_link text default null, p_data jsonb default '{}'::jsonb, p_dedupe_key text default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  c public.customers;
  r record;
  v_id uuid;
  v_first uuid;
begin
  select * into c from public.customers where id = p_customer_id;
  if c.id is null then
    return null;
  end if;
  if c.account_id is null then
    return public.notify(c.user_id, p_type, p_severity, p_title, p_message, p_link, p_data, p_dedupe_key);
  end if;
  for r in
    select m.user_id from public.customer_account_members m
    where m.account_id = c.account_id and m.status = 'active'
      and (case when p_audience = 'billing' then m.role in ('owner', 'admin')
                else m.all_branches or m.role in ('owner', 'admin')
                     or exists (select 1 from public.customer_member_branches b where b.member_id = m.id and b.customer_id = c.id)
           end)
  loop
    v_id := public.notify(r.user_id, p_type, p_severity, p_title, p_message, p_link, p_data,
                          case when p_dedupe_key is null then null else p_dedupe_key || ':' || r.user_id end);
    v_first := coalesce(v_first, v_id);
  end loop;
  return v_first;
end $$;

-- Creates a branch (customers row) for an account at a supplier. Internal.
create or replace function public.create_branch(
  p_account_id uuid, p_supplier_id uuid, p_branch_name text, p_contact_name text, p_phone text, p_address text,
  p_instructions text, p_household_type text, p_members_count integer, p_opening_stock integer,
  p_daily_consumption integer, p_actor uuid
) returns public.customers
language plpgsql security definer set search_path = public as $$
declare
  a public.customer_accounts;
  v_settings public.supplier_settings;
  v_owner uuid;
  v_head uuid;
  c public.customers;
begin
  select * into a from public.customer_accounts where id = p_account_id;
  select * into v_settings from public.supplier_settings where supplier_id = p_supplier_id;
  select owner_id into v_owner from public.suppliers where id = p_supplier_id;
  if p_opening_stock is not null and (p_opening_stock < 0 or p_opening_stock > 1000) then
    raise exception 'Opening stock must be between 0 and 1000 cans' using errcode = '22023';
  end if;
  if exists (select 1 from public.customers where account_id = p_account_id and supplier_id = p_supplier_id
             and lower(address) = lower(trim(p_address))) then
    raise exception 'This address is already connected to this supplier' using errcode = '23505';
  end if;
  -- One combined bill per account per supplier: later branches bill to the first.
  select id into v_head from public.customers
  where account_id = p_account_id and supplier_id = p_supplier_id and bill_to_customer_id is null
  order by created_at limit 1;

  insert into public.customers (user_id, supplier_id, account_id, branch_name, bill_to_customer_id, customer_name, phone,
                                address, delivery_instructions, daily_consumption, low_stock_threshold, critical_threshold,
                                safety_stock, household_type, members_count)
  values (a.owner_id, p_supplier_id, p_account_id, nullif(trim(coalesce(p_branch_name, '')), ''), v_head,
          trim(p_contact_name), nullif(trim(coalesce(p_phone, '')), ''), trim(p_address),
          nullif(trim(coalesce(p_instructions, '')), ''), coalesce(p_daily_consumption, 0),
          greatest(v_settings.default_low_stock_threshold, v_settings.default_critical_threshold),
          v_settings.default_critical_threshold, v_settings.default_safety_stock, p_household_type, p_members_count)
  returning * into c;
  insert into public.customer_stock (customer_id, supplier_id) values (c.id, c.supplier_id);
  if p_opening_stock is not null then
    insert into public.inventory_transactions (supplier_id, customer_id, transaction_type, quantity, reference_type,
                                               transaction_date, idempotency_key, created_by, notes)
    values (c.supplier_id, c.id, 'opening_stock', p_opening_stock, 'manual', public.customer_local_date(c.id),
            'opening:' || c.id, p_actor, 'Opening stock entered at registration');
  end if;
  perform public.notify(v_owner, 'account', 'info', 'New customer connected',
    format('%s%s joined your delivery list.', a.name, coalesce(' – ' || c.branch_name, '')),
    '/supplier/customers/' || c.id, jsonb_build_object('customer_id', c.id));
  perform public.write_audit('customer.connected', 'customer', c.id, c.supplier_id,
    jsonb_build_object('account_id', p_account_id, 'branch', c.branch_name, 'combined_bill_with', v_head));
  return c;
end $$;

-- ---------------------------------------------------------------------
-- Row Level Security for the new tables + policies that used user_id
-- ---------------------------------------------------------------------
alter table public.customer_accounts enable row level security;
alter table public.customer_account_members enable row level security;
alter table public.customer_member_branches enable row level security;
alter table public.customer_member_invites enable row level security;
alter table public.supplier_connection_requests enable row level security;

create policy accounts_select on public.customer_accounts for select to authenticated using (
  id in (select public.my_account_ids())
  or id in (select account_id from public.customers where supplier_id = public.my_supplier_id())
  or id in (select account_id from public.supplier_connection_requests where supplier_id = public.my_supplier_id())
  or public.is_admin()
);
create policy account_members_select on public.customer_account_members for select to authenticated using (
  user_id = auth.uid() or account_id in (select public.my_account_ids()) or public.is_admin()
);
create policy member_branches_select on public.customer_member_branches for select to authenticated using (
  member_id in (select id from public.customer_account_members where account_id in (select public.my_account_ids()))
  or public.is_admin()
);
create policy member_invites_select on public.customer_member_invites for select to authenticated using (
  public.my_account_role(account_id) in ('owner', 'admin') or public.is_admin()
);
create policy connection_requests_select on public.supplier_connection_requests for select to authenticated using (
  account_id in (select public.my_account_ids()) or supplier_id = public.my_supplier_id() or public.is_admin()
);
revoke insert, update, delete on public.customer_accounts, public.customer_account_members, public.customer_member_branches,
  public.customer_member_invites, public.supplier_connection_requests from authenticated;
revoke all on public.customer_accounts, public.customer_account_members, public.customer_member_branches,
  public.customer_member_invites, public.supplier_connection_requests from anon;

drop policy customers_select on public.customers;
create policy customers_select on public.customers for select to authenticated using (
  id in (select public.my_customer_ids()) or supplier_id = public.my_supplier_id() or public.is_admin()
);

drop policy suppliers_select on public.suppliers;
create policy suppliers_select on public.suppliers for select to authenticated using (
  owner_id = auth.uid()
  or id = public.my_supplier_id()
  or public.is_admin()
  or id in (select supplier_id from public.customers where id in (select public.my_customer_ids()))
  or id in (select supplier_id from public.supplier_connection_requests where account_id in (select public.my_account_ids()))
);

drop policy supplier_settings_select on public.supplier_settings;
create policy supplier_settings_select on public.supplier_settings for select to authenticated using (
  supplier_id = public.my_supplier_id()
  or public.is_admin()
  or supplier_id in (select supplier_id from public.customers where id in (select public.my_customer_ids()))
);

drop policy profiles_select on public.profiles;
create policy profiles_select on public.profiles for select to authenticated using (
  id = auth.uid()
  or public.is_admin()
  or id in (select user_id from public.customers where supplier_id = public.my_supplier_id())
  or id in (select user_id from public.supplier_staff where supplier_id = public.my_manager_supplier_id())
  or id in (select s.owner_id from public.suppliers s join public.customers c on c.supplier_id = s.id
            where c.id in (select public.my_customer_ids()))
  or id in (select user_id from public.customer_account_members where account_id in (select public.my_account_ids()))
);

-- Money: family/team Members do not see bills or payments.
do $$
declare t text;
begin
  foreach t in array array['invoices', 'credit_notes', 'payments'] loop
    execute format('drop policy %1$s_select on public.%1$I', t);
    execute format($f$
      create policy %1$s_select on public.%1$I for select to authenticated using (
        supplier_id = public.my_manager_supplier_id()
        or customer_id in (select public.my_billing_customer_ids())
        or public.is_admin()
      )$f$, t);
  end loop;
end $$;

-- Members of a customer account act on its branches (blocked-by-supplier check kept).

create or replace function public.customer_for_actor(p_customer_id uuid, p_allow_supplier boolean default false)
returns public.customers
language plpgsql stable security definer set search_path = public as $$
declare
  c public.customers;
begin
  perform public.require_auth();
  select * into c from public.customers where id = p_customer_id;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if c.id in (select public.my_customer_ids()) then
    if c.blocked_at is not null then
      raise exception 'This account has been blocked by your supplier. Please contact them.' using errcode = '42501';
    end if;
    return c;
  end if;
  if p_allow_supplier and (c.supplier_id = public.my_supplier_id() or public.is_admin()) then
    return c;
  end if;
  raise exception 'Not allowed for this customer' using errcode = '42501';
end $$;

create or replace function public.record_consumption(p_customer_id uuid, p_quantity integer, p_date date default null)
returns public.consumption_records
language plpgsql security definer set search_path = public as $$
declare
  c public.customers := public.customer_for_actor(p_customer_id, true);
  v_today date := public.customer_local_date(p_customer_id);
  v_date date := coalesce(p_date, v_today);
begin
  if c.user_id is not null and c.id not in (select public.my_customer_ids()) then
    raise exception 'Only the customer records consumption for app users' using errcode = '42501';
  end if;
  if v_date > v_today then
    raise exception 'Cannot record consumption for a future date' using errcode = '22023';
  end if;
  if v_date < v_today - 7 then
    raise exception 'Entries older than 7 days need a correction request to your supplier' using errcode = '22023';
  end if;
  return public.apply_consumption(c.id, v_date, p_quantity, 'manual', auth.uid());
end $$;

-- Notifications now reach every member with access to the branch.

create or replace function public.evaluate_stock_alert(p_customer_id uuid) returns public.stock_alert_level
language plpgsql security definer set search_path = public as $$
declare
  c record;
  s record;
  v_new public.stock_alert_level;
  v_rank_old int;
  v_rank_new int;
  v_owner uuid;
  v_notify_supplier boolean;
  v_msg text;
begin
  select * into c from public.customers where id = p_customer_id;
  select * into s from public.customer_stock where customer_id = p_customer_id for update;
  if c is null or s is null then
    return null;
  end if;

  -- Stock is "unconfirmed" until an opening stock or confirmed delivery exists.
  if not s.has_opening_stock then
    return 'none';
  end if;

  v_new := public.stock_level_for(s.current_stock, c.low_stock_threshold, c.critical_threshold);
  v_rank_old := array_position(array['none','low','critical']::text[], s.alert_level::text);
  v_rank_new := array_position(array['none','low','critical']::text[], v_new::text);

  if v_rank_new > v_rank_old and c.status = 'active' then
    if v_new = 'critical' then
      v_msg := case when s.current_stock = 0
        then 'You have run out of water cans. Order now to get water delivered.'
        else format('Water stock is critically low. You have %s can%s remaining. Order now to avoid running out of water.',
                    s.current_stock, case when s.current_stock = 1 then '' else 's' end)
      end;
      perform public.notify_customer(c.id, 'all', 'critical_stock', 'critical', 'Critical: water stock almost empty',
                            v_msg, '/app/order', jsonb_build_object('customer_id', c.id, 'stock', s.current_stock));
      select owner_id into v_owner from public.suppliers where id = c.supplier_id;
      select coalesce((notification_settings ->> 'notify_critical_customers')::boolean, true)
        into v_notify_supplier from public.supplier_settings where supplier_id = c.supplier_id;
      if coalesce(v_notify_supplier, true) then
        perform public.notify(v_owner, 'critical_stock', 'warning',
          format('%s is running out of water', c.customer_name),
          format('%s has %s can%s left.', c.customer_name, s.current_stock, case when s.current_stock = 1 then '' else 's' end),
          '/supplier/customers/' || c.id, jsonb_build_object('customer_id', c.id, 'stock', s.current_stock));
      end if;
    else
      perform public.notify_customer(c.id, 'all', 'low_stock', 'warning', 'Water stock is running low',
        format('You have %s cans remaining. Consider ordering soon.', s.current_stock),
        '/app/order', jsonb_build_object('customer_id', c.id, 'stock', s.current_stock));
    end if;
    update public.customer_stock set alert_level = v_new, last_alert_at = now() where customer_id = p_customer_id;
  elsif v_rank_new < v_rank_old then
    -- Stock went back up: reset alert state so the next drop alerts again.
    update public.customer_stock set alert_level = v_new where customer_id = p_customer_id;
  end if;
  return v_new;
end $$;

create or replace function public.refresh_prediction(p_customer_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  p jsonb := public.compute_prediction(p_customer_id);
  s public.customer_stock;
  c public.customers;
  v_open boolean;
begin
  select * into s from public.customer_stock where customer_id = p_customer_id;
  if s.customer_id is null then
    return p;
  end if;
  select * into c from public.customers where id = p_customer_id;
  select exists (select 1 from public.orders where customer_id = p_customer_id
                 and status in ('pending', 'accepted', 'preparing', 'out_for_delivery')) into v_open;

  update public.customer_stock set
    avg_daily_consumption = (p ->> 'avg_daily_consumption')::numeric,
    predicted_empty_date = (p ->> 'predicted_empty_date')::date,
    order_recommended = (p ->> 'order_now')::boolean,
    order_alert_sent = case when (p ->> 'order_now')::boolean then order_alert_sent else false end,
    prediction_refreshed_at = now()
  where customer_id = p_customer_id;

  -- One "order soon" reminder per low episode, skipped if an order is already open.
  if (p ->> 'order_now')::boolean and not s.order_alert_sent and not v_open and c.status = 'active'
     and (p ->> 'level') = 'ok' and (p ->> 'days_remaining') is not null then
    perform public.notify_customer(c.id, 'all', 'order_recommended', 'warning', 'Time to order water',
      format('Your water will last about %s day%s. Your supplier needs %s day%s to deliver. We recommend ordering %s cans now.',
             p ->> 'days_remaining', case when (p ->> 'days_remaining')::numeric = 1 then '' else 's' end,
             p ->> 'delivery_lead_days', case when (p ->> 'delivery_lead_days')::int = 1 then '' else 's' end,
             p ->> 'recommended_order_quantity'),
      '/app/order', p);
    update public.customer_stock set order_alert_sent = true where customer_id = p_customer_id;
  end if;
  return p;
end $$;

create or replace function public.adjust_delivery(p_delivery_id uuid, p_new_quantity integer, p_reason text)
returns public.delivery_adjustments
language plpgsql security definer set search_path = public as $$
declare
  d public.deliveries;
  c public.customers;
  a public.delivery_adjustments;
  v_prev integer;
begin
  perform public.require_auth();
  select * into d from public.deliveries where id = p_delivery_id for update;
  if d.id is null then
    raise exception 'Delivery not found' using errcode = 'P0002';
  end if;
  if not (d.supplier_id = public.my_supplier_id() or public.is_admin()) then
    raise exception 'Only the supplier can adjust a delivery' using errcode = '42501';
  end if;
  if d.supplier_id = public.my_supplier_id() then
    perform public.require_active_supplier();
  end if;
  if d.status <> 'confirmed' then
    raise exception 'Only confirmed deliveries can be adjusted' using errcode = '22023';
  end if;
  if p_reason is null or char_length(trim(p_reason)) < 3 then
    raise exception 'A reason is required for every adjustment' using errcode = '22023';
  end if;
  v_prev := d.confirmed_quantity + d.adjusted_quantity;
  if p_new_quantity = v_prev then
    raise exception 'New quantity equals the current quantity' using errcode = '22023';
  end if;

  insert into public.delivery_adjustments (delivery_id, supplier_id, customer_id, previous_quantity, new_quantity,
                                           unit_price, reason, adjusted_by)
  values (d.id, d.supplier_id, d.customer_id, v_prev, p_new_quantity, d.unit_price, trim(p_reason), auth.uid())
  returning * into a;

  insert into public.inventory_transactions (supplier_id, customer_id, transaction_type, quantity, reference_type,
                                             reference_id, transaction_date, idempotency_key, created_by, notes)
  values (d.supplier_id, d.customer_id, 'adjustment', a.delta, 'delivery_adjustment', a.id,
          public.customer_local_date(d.customer_id), 'delivery_adj:' || a.id, auth.uid(),
          format('Delivery %s corrected %s → %s: %s', to_char(d.delivery_date, 'DD Mon'), v_prev, p_new_quantity, a.reason));

  update public.deliveries set adjusted_quantity = adjusted_quantity + a.delta where id = d.id;

  select * into c from public.customers where id = d.customer_id;
  perform public.notify_customer(c.id, 'all', 'delivery_confirmed', 'info', 'Delivery corrected',
    format('Your %s delivery was corrected from %s to %s cans. Reason: %s',
           to_char(d.delivery_date, 'DD Mon'), v_prev, p_new_quantity, a.reason),
    '/app/deliveries', jsonb_build_object('delivery_id', d.id, 'adjustment_id', a.id));
  perform public.write_audit('delivery.adjusted', 'delivery', d.id, d.supplier_id,
    jsonb_build_object('from', v_prev, 'to', p_new_quantity, 'reason', a.reason));
  perform public.refresh_prediction(d.customer_id);
  return a;
end $$;

create or replace function public.resolve_correction_request(p_request_id uuid, p_approve boolean)
returns public.stock_correction_requests
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_active_supplier();
  r public.stock_correction_requests;
  c public.customers;
begin
  select * into r from public.stock_correction_requests where id = p_request_id and supplier_id = v_sid for update;
  if r.id is null then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if r.status <> 'pending' then
    raise exception 'Request already resolved' using errcode = '23505';
  end if;
  if p_approve then
    perform public.apply_consumption(r.customer_id, r.consumption_date, r.requested_quantity, 'correction', auth.uid());
  end if;
  update public.stock_correction_requests
     set status = case when p_approve then 'approved'::public.correction_status else 'rejected'::public.correction_status end,
         resolved_by = auth.uid(), resolved_at = now()
   where id = r.id returning * into r;
  select * into c from public.customers where id = r.customer_id;
  perform public.notify_customer(c.id, 'all', 'correction_request', 'info',
    case when p_approve then 'Correction approved' else 'Correction declined' end,
    format('Your correction for %s was %s.', to_char(r.consumption_date, 'DD Mon'),
           case when p_approve then 'approved and your stock was updated' else 'declined by your supplier' end),
    '/app/consumption', jsonb_build_object('request_id', r.id));
  perform public.write_audit('consumption.correction_' || r.status::text, 'stock_correction_request', r.id, v_sid,
                             jsonb_build_object('date', r.consumption_date, 'requested', r.requested_quantity));
  return r;
end $$;

create or replace function public.record_delivery(
  p_customer_id uuid,
  p_expected_quantity integer,
  p_actual_quantity integer,
  p_delivery_date date default null,
  p_order_id uuid default null,
  p_notes text default null
) returns public.deliveries
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_supplier_member();
  c public.customers;
  o public.orders;
  d public.deliveries;
  v_date date;
begin
  select * into c from public.customers where id = p_customer_id and supplier_id = v_sid;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if p_expected_quantity is null or p_actual_quantity is null
     or p_expected_quantity < 0 or p_actual_quantity < 0
     or p_expected_quantity > 1000 or p_actual_quantity > 1000 then
    raise exception 'Quantities must be between 0 and 1000' using errcode = '22023';
  end if;
  v_date := coalesce(p_delivery_date, public.customer_local_date(c.id));
  if v_date > public.customer_local_date(c.id) + 1 then
    raise exception 'Delivery date cannot be in the future' using errcode = '22023';
  end if;

  if p_order_id is not null then
    select * into o from public.orders where id = p_order_id for update;
    if o.id is null or o.customer_id <> c.id or o.supplier_id <> v_sid then
      raise exception 'Order does not belong to this customer' using errcode = '22023';
    end if;
    if o.status not in ('accepted', 'preparing', 'out_for_delivery') then
      raise exception 'Order must be accepted before it can be delivered (status: %)', o.status using errcode = '22023';
    end if;
    if exists (select 1 from public.deliveries where order_id = o.id and status <> 'cancelled') then
      raise exception 'A delivery is already recorded for this order' using errcode = '23505';
    end if;
  end if;

  insert into public.deliveries (supplier_id, customer_id, order_id, expected_quantity, actual_quantity, unit_price,
                                 delivery_date, notes, created_by)
  values (v_sid, c.id, p_order_id, p_expected_quantity, p_actual_quantity, public.effective_can_price(c.id),
          v_date, nullif(trim(coalesce(p_notes, '')), ''), auth.uid())
  returning * into d;

  if o.id is not null then
    insert into public.order_status_history (order_id, from_status, to_status, changed_by, reason)
    values (o.id, o.status, 'delivered', auth.uid(), 'Delivery recorded; awaiting customer confirmation');
    update public.orders set status = 'delivered' where id = o.id;
  end if;

  perform public.write_audit('delivery.recorded', 'delivery', d.id, v_sid,
    jsonb_build_object('expected', p_expected_quantity, 'actual', p_actual_quantity));

  if c.user_id is null then
    -- Offline customer: supplier confirms on their behalf (flagged for reporting).
    d := public.apply_delivery_confirmation(d.id, p_actual_quantity, 'Confirmed by supplier (offline customer)', true);
  else
    perform public.notify_customer(c.id, 'all', 'delivery_confirmation_required', 'warning',
      'Please confirm your water delivery',
      format('Your supplier recorded %s can%s delivered on %s. Confirm how many you actually received.',
             p_actual_quantity, case when p_actual_quantity = 1 then '' else 's' end, to_char(v_date, 'DD Mon')),
      '/app/deliveries', jsonb_build_object('delivery_id', d.id), 'confirm_delivery:' || d.id);
  end if;
  return d;
end $$;

create or replace function public.update_order_status(
  p_order_id uuid, p_status public.order_status, p_scheduled_date date default null, p_reason text default null
) returns public.orders
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_supplier_member();
  o public.orders;
  c public.customers;
  v_from public.order_status;
  v_sched_changed boolean;
begin
  select * into o from public.orders where id = p_order_id and supplier_id = v_sid for update;
  if o.id is null then
    raise exception 'Order not found' using errcode = 'P0002';
  end if;
  if p_status = 'delivered' then
    raise exception 'Record a delivery to complete an order (customer confirmation required)' using errcode = '22023';
  end if;
  v_from := o.status;
  if p_status <> v_from and not public.order_transition_allowed(v_from, p_status) then
    raise exception 'Cannot move order from % to %', v_from, p_status using errcode = '22023';
  end if;
  if p_status = 'rejected' and (p_reason is null or char_length(trim(p_reason)) < 3) then
    raise exception 'Please give a reason when rejecting an order' using errcode = '22023';
  end if;
  v_sched_changed := p_scheduled_date is not null and p_scheduled_date is distinct from o.scheduled_date;

  update public.orders set status = p_status,
    scheduled_date = coalesce(p_scheduled_date, scheduled_date),
    status_reason = coalesce(p_reason, status_reason)
  where id = o.id returning * into o;

  if p_status <> v_from then
    insert into public.order_status_history (order_id, from_status, to_status, changed_by, reason)
    values (o.id, v_from, p_status, auth.uid(), p_reason);
  end if;

  select * into c from public.customers where id = o.customer_id;
  if p_status <> v_from then
    perform public.notify(c.user_id,
      case when p_status = 'accepted' then 'order_accepted' else 'order_status' end,
      case when p_status in ('rejected', 'cancelled') then 'warning' else 'info' end,
      case p_status
        when 'accepted' then 'Order accepted'
        when 'preparing' then 'Your order is being prepared'
        when 'out_for_delivery' then 'Water is on the way!'
        when 'rejected' then 'Order could not be accepted'
        when 'cancelled' then 'Order cancelled by supplier'
        else 'Order updated' end,
      format('Your order for %s cans is now %s.%s', o.quantity, replace(p_status::text, '_', ' '),
             coalesce(' ' || p_reason, '')),
      '/app/orders', jsonb_build_object('order_id', o.id, 'status', p_status));
  end if;
  if v_sched_changed then
    perform public.notify_customer(c.id, 'all', 'delivery_scheduled', 'info', 'Delivery scheduled',
      format('Your %s-can delivery is scheduled for %s.', o.quantity, to_char(o.scheduled_date, 'Dy, DD Mon')),
      '/app/orders', jsonb_build_object('order_id', o.id, 'scheduled_date', o.scheduled_date));
  end if;
  perform public.write_audit('order.' || p_status::text, 'order', o.id, v_sid,
                             jsonb_build_object('from', v_from, 'scheduled_date', o.scheduled_date));
  perform public.refresh_prediction(c.id);
  return o;
end $$;

create or replace function public.set_customer_blocked(p_customer_id uuid, p_blocked boolean, p_reason text default null)
returns public.customers
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_active_supplier();
  c public.customers;
begin
  if p_blocked and (p_reason is null or char_length(trim(p_reason)) < 3) then
    raise exception 'Please give a reason for blocking' using errcode = '22023';
  end if;
  perform set_config('waterdrop.block_change', 'on', true);
  update public.customers set
    blocked_at = case when p_blocked then now() else null end,
    block_reason = case when p_blocked then trim(p_reason) else null end,
    blocked_by = case when p_blocked then auth.uid() else null end
  where id = p_customer_id and supplier_id = v_sid
  returning * into c;
  perform set_config('waterdrop.block_change', 'off', true);
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  perform public.notify_customer(c.id, 'all', 'account', case when p_blocked then 'critical' else 'success' end,
    case when p_blocked then 'Account blocked by your supplier' else 'Account unblocked' end,
    case when p_blocked then format('Your supplier blocked this account: %s', c.block_reason)
         else 'You can order water again.' end, '/app', '{}'::jsonb);
  perform public.write_audit(case when p_blocked then 'customer.blocked' else 'customer.unblocked' end,
                             'customer', c.id, v_sid, jsonb_build_object('reason', p_reason));
  return c;
end $$;

create or replace function public.process_payment_reminders(p_today date default current_date) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  i record;
  v_due integer := 0;
  v_overdue integer := 0;
  v_job bigint := public.start_job('payment_reminders', p_today::text);
  v_inv public.invoices;
begin
  for i in select inv.id from public.invoices inv where inv.superseded_by is null and inv.status <> 'paid' loop
    v_inv := public.refresh_invoice_status(i.id, p_today);
    if v_inv.status = 'paid' then
      continue;
    end if;
    if v_inv.due_date between p_today and p_today + 3 then
      if public.notify_customer(v_inv.customer_id, 'billing', 'payment_due', 'warning',
           'Water bill due soon',
           format('Bill %s: ₹%s due on %s.', v_inv.invoice_number,
                  to_char(v_inv.amount_due - v_inv.amount_paid, 'FM999999990.00'), to_char(v_inv.due_date, 'DD Mon')),
           '/app/bills', jsonb_build_object('invoice_id', v_inv.id), 'due:' || v_inv.id) is not null then
        v_due := v_due + 1;
      end if;
    elsif v_inv.status = 'overdue' then
      if public.notify_customer(v_inv.customer_id, 'billing', 'payment_overdue', 'critical',
           'Water bill overdue',
           format('Bill %s is overdue. Outstanding ₹%s (due %s).', v_inv.invoice_number,
                  to_char(v_inv.amount_due - v_inv.amount_paid, 'FM999999990.00'), to_char(v_inv.due_date, 'DD Mon')),
           '/app/bills', jsonb_build_object('invoice_id', v_inv.id),
           'overdue:' || v_inv.id || ':' || to_char(p_today, 'IYYY-IW')) is not null then
        v_overdue := v_overdue + 1;
      end if;
    end if;
  end loop;
  if v_job is not null then
    perform public.finish_job(v_job, jsonb_build_object('due', v_due, 'overdue', v_overdue));
  end if;
  return jsonb_build_object('due_reminders', v_due, 'overdue_reminders', v_overdue);
end $$;

-- Combined bills: a head branch is billed for itself and the branches that bill to it.

create or replace function public.customer_balance(p_customer_id uuid) returns numeric
language sql stable security definer set search_path = public as $$
  with g as (select public.billing_group(public.head_customer_id(p_customer_id)) as id)
  select round(
      coalesce((select sum(opening_balance) from public.customers where id in (select id from g)), 0)
    + coalesce((select sum(current_charges) from public.invoices where customer_id in (select id from g)), 0)
    - coalesce((select sum(amount) from public.payments where customer_id in (select id from g) and status = 'succeeded'), 0)
    - coalesce((select sum(amount) from public.credit_notes where customer_id in (select id from g)), 0), 2);
$$;

create or replace function public.customer_unbilled(p_customer_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  with d as (
    select dl.confirmed_quantity as qty, dl.confirmed_quantity * dl.unit_price as amount
    from public.deliveries dl
    where dl.customer_id in (select public.billing_group(public.head_customer_id(p_customer_id))) and dl.status = 'confirmed'
      and not exists (select 1 from public.invoice_items ii where ii.delivery_id = dl.id)
    union all
    select a.delta, a.delta * a.unit_price
    from public.delivery_adjustments a
    where a.customer_id in (select public.billing_group(public.head_customer_id(p_customer_id)))
      and not exists (select 1 from public.invoice_items ii where ii.delivery_adjustment_id = a.id)
  )
  select jsonb_build_object('quantity', coalesce(sum(qty), 0), 'amount', round(coalesce(sum(amount), 0), 2)) from d;
$$;

create or replace function public.refresh_invoice_status(p_invoice_id uuid, p_today date default current_date) returns public.invoices
language plpgsql security definer set search_path = public as $$
declare
  i public.invoices;
  v_next timestamptz;
  v_paid numeric;
  v_status public.invoice_status;
begin
  select * into i from public.invoices where id = p_invoice_id;
  if i.id is null then
    return null;
  end if;
  select generated_at into v_next from public.invoices where id = i.superseded_by;
  -- Settled amount = payments + credits received after this invoice (until superseded)
  select coalesce((select sum(amount) from public.payments
                    where customer_id in (select public.billing_group(i.customer_id)) and status = 'succeeded'
                      and received_at > i.generated_at and (v_next is null or received_at <= v_next)), 0)
       + coalesce((select sum(amount) from public.credit_notes
                    where customer_id in (select public.billing_group(i.customer_id))
                      and created_at > i.generated_at and (v_next is null or created_at <= v_next)), 0)
    into v_paid;

  v_status := case
    when i.amount_due <= 0 or v_paid >= i.amount_due then 'paid'
    when i.due_date < p_today then 'overdue'
    when v_paid > 0 then 'partially_paid'
    else 'unpaid'
  end;
  update public.invoices set amount_paid = round(v_paid, 2), status = v_status
   where id = i.id and (amount_paid is distinct from round(v_paid, 2) or status is distinct from v_status)
  returning * into i;
  if i.id is null then
    select * into i from public.invoices where id = p_invoice_id;
  end if;
  return i;
end $$;

create or replace function public.generate_invoice_for_customer(
  p_customer_id uuid, p_period_start date, p_period_end date, p_invoice_date date default current_date
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  c public.customers;
  sup public.suppliers;
  st public.supplier_settings;
  prev public.invoices;
  v_existing uuid;
  v_inv uuid;
  v_number text;
  v_seq integer;
  v_qty integer;
  v_subtotal numeric;
  v_tax numeric;
  v_payments numeric;
  v_credits numeric;
  v_prev_balance numeric;
  v_due numeric;
  v_items integer;
  v_now timestamptz;
  v_multi boolean;
begin
  if p_period_end < p_period_start then
    raise exception 'Invalid billing period' using errcode = '22023';
  end if;
  -- Lock the customer: serializes billing with payments/credits for this account.
  select * into c from public.customers where id = p_customer_id for update;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  -- Branches that bill to a head branch appear on the head branch's combined bill.
  if c.bill_to_customer_id is not null then
    return null;
  end if;
  v_multi := exists (select 1 from public.customers where bill_to_customer_id = c.id);

  select id into v_existing from public.invoices
   where customer_id = c.id and billing_period_start = p_period_start and billing_period_end = p_period_end;
  if v_existing is not null then
    return v_existing;   -- idempotent re-run
  end if;

  select * into sup from public.suppliers where id = c.supplier_id;
  select * into st from public.supplier_settings where supplier_id = c.supplier_id for update;
  select * into prev from public.invoices where customer_id = c.id order by generated_at desc limit 1;

  create temporary table if not exists _wd_items (
    delivery_id uuid, adjustment_id uuid, item_date date, description text, quantity integer, unit_price numeric, amount numeric
  ) on commit drop;
  truncate _wd_items;

  insert into _wd_items
  select d.id, null, d.delivery_date,
         case when v_multi then coalesce(b.branch_name, b.customer_name) || ' – ' else '' end ||
         format('Water cans delivered (confirmed %s of %s expected)', d.confirmed_quantity, d.expected_quantity),
         d.confirmed_quantity, d.unit_price, round(d.confirmed_quantity * d.unit_price, 2)
  from public.deliveries d join public.customers b on b.id = d.customer_id
  where (b.id = c.id or b.bill_to_customer_id = c.id) and d.status = 'confirmed' and d.delivery_date <= p_period_end
    and not exists (select 1 from public.invoice_items ii where ii.delivery_id = d.id);

  insert into _wd_items
  select null, a.id, (a.created_at at time zone c.timezone)::date,
         case when v_multi then coalesce(b.branch_name, b.customer_name) || ' – ' else '' end ||
         format('Delivery correction: %s', a.reason), a.delta, a.unit_price, round(a.delta * a.unit_price, 2)
  from public.delivery_adjustments a join public.customers b on b.id = a.customer_id
  where (b.id = c.id or b.bill_to_customer_id = c.id) and (a.created_at at time zone c.timezone)::date <= p_period_end
    and not exists (select 1 from public.invoice_items ii where ii.delivery_adjustment_id = a.id);

  select count(*), coalesce(sum(quantity), 0), coalesce(sum(amount), 0) into v_items, v_qty, v_subtotal from _wd_items;

  v_now := clock_timestamp();
  v_prev_balance := coalesce(prev.amount_due,
    (select sum(opening_balance) from public.customers where id in (select public.billing_group(c.id))), 0);
  select coalesce(sum(amount), 0) into v_payments from public.payments
   where customer_id in (select public.billing_group(c.id)) and status = 'succeeded'
     and (prev.id is null or received_at > prev.generated_at) and received_at <= v_now;
  select coalesce(sum(amount), 0) into v_credits from public.credit_notes
   where customer_id in (select public.billing_group(c.id)) and (prev.id is null or created_at > prev.generated_at) and created_at <= v_now;

  -- Nothing to bill and nothing carried: skip (safe to re-run later).
  if v_items = 0 and v_prev_balance = 0 and v_payments = 0 and v_credits = 0 then
    return null;
  end if;

  v_tax := round(v_subtotal * st.tax_rate / 100, 2);
  v_due := round(v_prev_balance + v_subtotal + v_tax - v_payments - v_credits, 2);

  perform set_config('waterdrop.billing_engine', 'on', true);
  update public.supplier_settings set invoice_seq = invoice_seq + 1 where id = st.id returning invoice_seq into v_seq;
  perform set_config('waterdrop.billing_engine', 'off', true);
  v_number := st.invoice_prefix || '-' || sup.business_code || '-' || to_char(p_invoice_date, 'YYYYMM') || '-' || lpad(v_seq::text, 4, '0');

  insert into public.invoices (supplier_id, customer_id, invoice_number, invoice_date, billing_period_start,
    billing_period_end, total_quantity, subtotal, tax_rate, tax_amount, current_charges, previous_balance,
    payments_received, credits, amount_due, due_date, status, supplier_snapshot, customer_snapshot, generated_at)
  values (c.supplier_id, c.id, v_number, p_invoice_date, p_period_start, p_period_end, v_qty, v_subtotal,
    st.tax_rate, v_tax, v_subtotal + v_tax, v_prev_balance, v_payments, v_credits, v_due,
    p_invoice_date + st.billing_due_days,
    case when v_due <= 0 then 'paid'::public.invoice_status else 'unpaid'::public.invoice_status end,
    jsonb_build_object('business_name', sup.business_name, 'owner_name', sup.owner_name, 'address', sup.address,
                       'phone', sup.phone, 'email', sup.email, 'logo_url', sup.logo_url, 'billing_info', sup.billing_info,
                       'business_code', sup.business_code, 'tax_label', st.tax_label),
    jsonb_build_object('customer_name', coalesce((select name from public.customer_accounts where id = c.account_id), c.customer_name),
                       'address', c.address, 'phone', c.phone, 'branch_name', c.branch_name,
                       'branches', (select jsonb_agg(coalesce(x.branch_name, x.customer_name) order by x.created_at)
                                    from public.customers x where x.id = c.id or x.bill_to_customer_id = c.id)),
    v_now)
  returning id into v_inv;

  insert into public.invoice_items (invoice_id, delivery_id, delivery_adjustment_id, item_date, description, quantity, unit_price, amount)
  select v_inv, delivery_id, adjustment_id, item_date, description, quantity, unit_price, amount
  from _wd_items order by item_date, description;

  if prev.id is not null then
    update public.invoices set superseded_by = v_inv where id = prev.id;
    perform public.refresh_invoice_status(prev.id);
  end if;

  perform public.notify_customer(c.id, 'billing', 'bill_generated', 'info', 'Your monthly water bill is ready',
    format('Bill %s for %s – %s: %s cans. Amount due ₹%s by %s.', v_number, to_char(p_period_start, 'DD Mon'),
           to_char(p_period_end, 'DD Mon YYYY'), v_qty, to_char(v_due, 'FM999999990.00'),
           to_char(p_invoice_date + st.billing_due_days, 'DD Mon')),
    '/app/bills', jsonb_build_object('invoice_id', v_inv), 'bill:' || v_inv);
  update public.invoices set notified_at = now() where id = v_inv;
  perform public.write_audit('invoice.generated', 'invoice', v_inv, c.supplier_id,
    jsonb_build_object('number', v_number, 'amount_due', v_due, 'quantity', v_qty));
  return v_inv;
end $$;

create or replace function public.finalize_payment(p_payment_id uuid, p_verified_by uuid) returns public.payments
language plpgsql security definer set search_path = public as $$
declare
  p public.payments;
  c public.customers;
  v_inv uuid;
begin
  select * into p from public.payments where id = p_payment_id;
  -- Same lock as billing so payment windows never straddle an invoice boundary.
  select * into c from public.customers where id = public.head_customer_id(p.customer_id) for update;
  select * into p from public.payments where id = p_payment_id for update;
  if p.status = 'succeeded' then
    return p;  -- idempotent
  end if;
  if p.status not in ('pending') then
    raise exception 'Payment is %', p.status using errcode = '22023';
  end if;
  v_inv := coalesce(p.invoice_id,
    (select id from public.invoices where customer_id = c.id and superseded_by is null
      order by generated_at desc limit 1));

  update public.payments set status = 'succeeded', received_at = clock_timestamp(), verified_by = p_verified_by,
         verified_at = now(), invoice_id = v_inv
   where id = p.id returning * into p;

  if v_inv is not null then
    insert into public.payment_allocations (payment_id, invoice_id, amount) values (p.id, v_inv, p.amount)
    on conflict do nothing;
    perform public.refresh_invoice_status(v_inv);
  end if;

  perform public.notify_customer(c.id, 'billing', 'payment_received', 'success', 'Payment received',
    format('₹%s received via %s. Thank you!', to_char(p.amount, 'FM999999990.00'), replace(p.payment_method::text, '_', ' ')),
    '/app/payments', jsonb_build_object('payment_id', p.id), 'payment_received:' || p.id);
  perform public.write_audit('payment.succeeded', 'payment', p.id, p.supplier_id,
    jsonb_build_object('amount', p.amount, 'method', p.payment_method, 'invoice_id', v_inv));
  return p;
end $$;

create or replace function public.verify_payment(p_payment_id uuid, p_approve boolean, p_note text default null)
returns public.payments
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_active_supplier();
  p public.payments;
  c public.customers;
begin
  select * into p from public.payments where id = p_payment_id and supplier_id = v_sid;
  if p.id is null then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if p.status <> 'pending' then
    raise exception 'Payment already %', p.status using errcode = '23505';
  end if;
  if p.payment_method = 'online' then
    raise exception 'Online payments are verified by the gateway webhook only' using errcode = '42501';
  end if;
  if p_approve then
    return public.finalize_payment(p.id, auth.uid());
  end if;
  update public.payments set status = 'failed', verified_by = auth.uid(), verified_at = now(),
         notes = coalesce(p_note, notes) where id = p.id returning * into p;
  select * into c from public.customers where id = p.customer_id;
  perform public.notify_customer(c.id, 'billing', 'payment_received', 'warning', 'Payment could not be verified',
    format('Your payment of ₹%s (ref %s) was not verified by your supplier.%s',
           to_char(p.amount, 'FM999999990.00'), coalesce(p.reference_number, '—'), coalesce(' ' || p_note, '')),
    '/app/payments', jsonb_build_object('payment_id', p.id));
  perform public.write_audit('payment.rejected', 'payment', p.id, v_sid, jsonb_build_object('note', p_note));
  return p;
end $$;

create or replace function public.issue_credit_note(
  p_customer_id uuid, p_amount numeric, p_reason text, p_invoice_id uuid default null
) returns public.credit_notes
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_active_supplier();
  c public.customers;
  cn public.credit_notes;
  v_latest uuid;
  v_code text;
begin
  select * into c from public.customers where id = p_customer_id and supplier_id = v_sid for update;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if p_reason is null or char_length(trim(p_reason)) < 3 then
    raise exception 'A reason is required' using errcode = '22023';
  end if;
  if p_invoice_id is not null and not exists (select 1 from public.invoices where id = p_invoice_id and customer_id = c.id) then
    raise exception 'Invoice does not belong to this customer' using errcode = '22023';
  end if;
  select business_code into v_code from public.suppliers where id = v_sid;
  insert into public.credit_notes (supplier_id, customer_id, invoice_id, credit_number, amount, reason, created_by)
  values (v_sid, c.id, p_invoice_id,
          'CN-' || v_code || '-' || to_char(now(), 'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6),
          round(p_amount, 2), trim(p_reason), auth.uid())
  returning * into cn;
  select id into v_latest from public.invoices where customer_id = public.head_customer_id(c.id) and superseded_by is null order by generated_at desc limit 1;
  if v_latest is not null then
    perform public.refresh_invoice_status(v_latest);
  end if;
  perform public.notify_customer(c.id, 'billing', 'payment_received', 'success', 'Credit applied to your account',
    format('A credit of ₹%s was applied: %s', to_char(cn.amount, 'FM999999990.00'), cn.reason),
    '/app/bills', jsonb_build_object('credit_note_id', cn.id));
  perform public.write_audit('credit_note.issued', 'credit_note', cn.id, v_sid,
    jsonb_build_object('amount', cn.amount, 'reason', cn.reason));
  return cn;
end $$;

create or replace function public.submit_payment(
  p_customer_id uuid, p_amount numeric, p_method public.payment_method, p_reference text default null,
  p_payment_date date default current_date, p_invoice_id uuid default null, p_notes text default null
) returns public.payments
language plpgsql security definer set search_path = public as $$
declare
  c public.customers := public.customer_for_billing(p_customer_id);
  p public.payments;
  v_owner uuid;
begin
  if p_method = 'online' then
    raise exception 'Use "Pay online" for gateway payments' using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be greater than zero' using errcode = '22023';
  end if;
  if p_method in ('upi', 'bank_transfer') and (p_reference is null or char_length(trim(p_reference)) < 4) then
    raise exception 'Please enter the UPI / bank transaction reference' using errcode = '22023';
  end if;
  if p_invoice_id is not null and not exists (select 1 from public.invoices where id = p_invoice_id and customer_id = c.id) then
    raise exception 'Invoice does not belong to you' using errcode = '22023';
  end if;
  insert into public.payments (supplier_id, customer_id, invoice_id, amount, payment_method, reference_number,
                               payment_date, status, submitted_by_customer, recorded_by, notes)
  values (c.supplier_id, c.id, p_invoice_id, round(p_amount, 2), p_method, nullif(trim(coalesce(p_reference, '')), ''),
          coalesce(p_payment_date, current_date), 'pending', true, auth.uid(), p_notes)
  returning * into p;
  select owner_id into v_owner from public.suppliers where id = c.supplier_id;
  perform public.notify(v_owner, 'payment_submitted', 'info', 'Payment needs verification',
    format('%s reported paying ₹%s via %s (ref %s).', c.customer_name, to_char(p.amount, 'FM999999990.00'),
           replace(p.payment_method::text, '_', ' '), coalesce(p.reference_number, '—')),
    '/supplier/payments', jsonb_build_object('payment_id', p.id));
  return p;
end $$;

create or replace function public.create_gateway_payment(
  p_customer_id uuid, p_amount numeric, p_gateway text, p_gateway_order_id text, p_actor uuid
) returns public.payments
language plpgsql security definer set search_path = public as $$
declare
  c public.customers;
  p public.payments;
begin
  select * into c from public.customers where id = p_customer_id;
  if c.id is null or not (
       (c.account_id is null and c.user_id = p_actor)
       or exists (select 1 from public.customer_account_members m where m.account_id = c.account_id
                  and m.user_id = p_actor and m.status = 'active' and m.role in ('owner', 'admin'))) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  insert into public.payments (supplier_id, customer_id, amount, payment_method, payment_date, status,
                               submitted_by_customer, gateway, gateway_order_id, recorded_by,
                               invoice_id)
  values (c.supplier_id, c.id, round(p_amount, 2), 'online', current_date, 'pending', true, p_gateway,
          p_gateway_order_id, p_actor,
          (select id from public.invoices where customer_id = public.head_customer_id(c.id) and superseded_by is null order by generated_at desc limit 1))
  returning * into p;
  return p;
end $$;

create or replace function public.get_customer_summary(p_customer_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.customers := public.customer_for_actor(p_customer_id, true);
  v_pred jsonb := public.compute_prediction(p_customer_id);
  v_latest_order jsonb;
  v_next_delivery date;
  v_pending_conf integer;
  v_latest_invoice jsonb;
  v_money boolean;
begin
  select to_jsonb(o) into v_latest_order from (
    select id, quantity, status, requested_delivery_date, scheduled_date, is_bulk, created_at
    from public.orders where customer_id = c.id order by created_at desc limit 1) o;

  select min(coalesce(scheduled_date, requested_delivery_date)) into v_next_delivery
  from public.orders where customer_id = c.id and status in ('pending', 'accepted', 'preparing', 'out_for_delivery');

  select count(*) into v_pending_conf from public.deliveries where customer_id = c.id and status = 'awaiting_confirmation';

  select to_jsonb(i) into v_latest_invoice from (
    select id, invoice_number, amount_due, amount_paid, due_date, status, billing_period_start, billing_period_end
    from public.invoices where customer_id = public.head_customer_id(c.id) order by generated_at desc limit 1) i;
  -- Family / team members with the Member role do not see money.
  v_money := c.id not in (select public.my_customer_ids()) or c.id in (select public.my_billing_customer_ids());

  return jsonb_build_object(
    'customer_id', c.id,
    'customer_name', c.customer_name,
    'supplier_id', c.supplier_id,
    'thresholds', jsonb_build_object('low', c.low_stock_threshold, 'critical', c.critical_threshold),
    'prediction', v_pred,
    'latest_order', v_latest_order,
    'next_delivery_date', v_next_delivery,
    'pending_confirmations', v_pending_conf,
    'latest_invoice', case when v_money then v_latest_invoice end,
    'outstanding_balance', case when v_money then public.customer_balance(c.id) else 0 end,
    'unbilled', case when v_money then public.customer_unbilled(c.id) else jsonb_build_object('quantity', 0, 'amount', 0) end,
    'can_see_money', v_money
  );
end $$;

create or replace function public.get_supplier_dashboard() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_sid uuid := public.my_supplier_id();
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_month_start date := date_trunc('month', v_today)::date;
begin
  if v_sid is null then
    raise exception 'Supplier account required' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'today', v_today,
    'total_customers', (select count(*) from public.customers where supplier_id = v_sid and status = 'active'),
    'todays_orders', (select count(*) from public.orders where supplier_id = v_sid
                       and (created_at at time zone 'Asia/Kolkata')::date = v_today),
    'pending_orders', (select count(*) from public.orders where supplier_id = v_sid and status = 'pending'),
    'pending_deliveries', (select count(*) from public.orders where supplier_id = v_sid
                            and status in ('accepted', 'preparing', 'out_for_delivery')),
    'awaiting_confirmation', (select count(*) from public.deliveries where supplier_id = v_sid and status = 'awaiting_confirmation'),
    'delivered_today', (select coalesce(sum(confirmed_quantity + adjusted_quantity), 0) from public.deliveries
                         where supplier_id = v_sid and status = 'confirmed' and delivery_date = v_today),
    'delivered_this_month', (select coalesce(sum(confirmed_quantity + adjusted_quantity), 0) from public.deliveries
                              where supplier_id = v_sid and status = 'confirmed' and delivery_date >= v_month_start),
    'revenue_this_month', (select coalesce(round(sum((confirmed_quantity + adjusted_quantity) * unit_price), 2), 0)
                            from public.deliveries
                            where supplier_id = v_sid and status = 'confirmed' and delivery_date >= v_month_start),
    'collected_this_month', (select coalesce(sum(amount), 0) from public.payments
                              where supplier_id = v_sid and status = 'succeeded' and payment_date >= v_month_start),
    'outstanding_total', (select coalesce(sum(greatest(public.customer_balance(id), 0)), 0)
                           from public.customers where supplier_id = v_sid and bill_to_customer_id is null),
    'pending_payment_verifications', (select count(*) from public.payments where supplier_id = v_sid
                                       and status = 'pending' and payment_method <> 'online'),
    'needs_delivery_today', coalesce((select jsonb_agg(x order by x->>'date') from (
        select jsonb_build_object('order_id', o.id, 'customer_id', c.id, 'customer_name', c.customer_name,
                                  'address', c.address, 'quantity', o.quantity, 'status', o.status,
                                  'date', coalesce(o.scheduled_date, o.requested_delivery_date)) as x
        from public.orders o join public.customers c on c.id = o.customer_id
        where o.supplier_id = v_sid and o.status in ('pending', 'accepted', 'preparing', 'out_for_delivery')
          and coalesce(o.scheduled_date, o.requested_delivery_date, v_today) <= v_today
        limit 50) t), '[]'::jsonb),
    'low_stock_customers', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('customer_id', c.id, 'customer_name', c.customer_name, 'stock', s.current_stock,
                                  'level', public.stock_level_for(s.current_stock, c.low_stock_threshold, c.critical_threshold),
                                  'predicted_empty_date', s.predicted_empty_date,
                                  'has_open_order', exists (select 1 from public.orders o where o.customer_id = c.id
                                     and o.status in ('pending','accepted','preparing','out_for_delivery'))) as x
        from public.customers c join public.customer_stock s on s.customer_id = c.id
        where c.supplier_id = v_sid and c.status = 'active' and s.has_opening_stock
          and (s.current_stock <= c.low_stock_threshold or s.order_recommended)
        order by s.current_stock asc limit 50) t), '[]'::jsonb),
    'discrepancy_customers', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('customer_id', c.id, 'customer_name', c.customer_name,
                                  'deliveries', count(*), 'total_shortage', sum(-d.discrepancy)) as x
        from public.deliveries d join public.customers c on c.id = d.customer_id
        where d.supplier_id = v_sid and d.status = 'confirmed' and d.discrepancy < 0
          and d.delivery_date >= v_today - 30
        group by c.id, c.customer_name order by sum(-d.discrepancy) desc limit 20) t), '[]'::jsonb),
    'outstanding_customers', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('customer_id', c.id, 'customer_name', c.customer_name,
                                  'balance', public.customer_balance(c.id)) as x
        from public.customers c where c.supplier_id = v_sid and c.bill_to_customer_id is null and public.customer_balance(c.id) > 0
        order by public.customer_balance(c.id) desc limit 20) t), '[]'::jsonb)
  );
end $$;

create or replace function public.report_outstanding(p_supplier_id uuid default null)
returns table (customer_name text, phone text, balance numeric, last_invoice text, last_due_date date,
               last_payment_date date, overdue boolean)
language sql stable security definer set search_path = public as $$
  select c.customer_name, c.phone, public.customer_balance(c.id),
         li.invoice_number, li.due_date,
         (select max(payment_date) from public.payments p where p.customer_id = c.id and p.status = 'succeeded'),
         coalesce(li.status = 'overdue', false)
  from public.customers c
  left join lateral (select invoice_number, due_date, status from public.invoices i
                     where i.customer_id = c.id order by generated_at desc limit 1) li on true
  where c.supplier_id = public.report_scope(p_supplier_id) and c.bill_to_customer_id is null and public.customer_balance(c.id) <> 0
  order by public.customer_balance(c.id) desc;
$$;

drop function public.list_supplier_customers();
create or replace function public.list_supplier_customers()
returns table (
  id uuid, customer_name text, phone text, address text, status public.customer_status, has_app boolean,
  current_stock integer, stock_confirmed boolean, level text, predicted_empty_date date,
  daily_consumption integer, can_price numeric, balance numeric, created_at timestamptz,
  household_type text, members_count integer, blocked boolean,
  account_name text, account_type text, branch_name text, bill_to_customer_id uuid
)
language sql stable security definer set search_path = public as $$
  select c.id, c.customer_name, c.phone, c.address, c.status, c.user_id is not null,
         coalesce(s.current_stock, 0), coalesce(s.has_opening_stock, false),
         case when not coalesce(s.has_opening_stock, false) then 'unknown'
              else case public.stock_level_for(s.current_stock, c.low_stock_threshold, c.critical_threshold)
                     when 'critical' then 'critical' when 'low' then 'low' else 'ok' end end,
         s.predicted_empty_date, c.daily_consumption, public.effective_can_price(c.id),
         case when c.bill_to_customer_id is null then public.customer_balance(c.id) end, c.created_at,
         c.household_type, c.members_count, c.blocked_at is not null,
         a.name, a.account_type::text, c.branch_name, c.bill_to_customer_id
  from public.customers c left join public.customer_stock s on s.customer_id = c.id
  left join public.customer_accounts a on a.id = c.account_id
  where c.supplier_id = public.my_supplier_id()
  order by c.customer_name;
$$;

drop function public.admin_list_customers(text);
create or replace function public.admin_list_customers(p_search text default null)
returns table (id uuid, customer_name text, phone text, supplier_name text, has_app boolean, user_id uuid,
               user_disabled boolean, status public.customer_status, current_stock integer, balance numeric, created_at timestamptz,
               account_name text, account_type text, branch_name text)
language sql stable security definer set search_path = public as $$
  select c.id, c.customer_name, c.phone, s.business_name, c.user_id is not null, c.user_id,
         coalesce(pr.is_disabled, false), c.status, coalesce(cs.current_stock, 0), public.customer_balance(c.id), c.created_at,
         a.name, a.account_type::text, c.branch_name
  from public.customers c
  join public.suppliers s on s.id = c.supplier_id
  left join public.profiles pr on pr.id = c.user_id
  left join public.customer_stock cs on cs.customer_id = c.id
  left join public.customer_accounts a on a.id = c.account_id
  where public.is_admin()
    and (p_search is null or c.customer_name ilike '%' || p_search || '%' or c.phone ilike '%' || p_search || '%'
         or a.name ilike '%' || p_search || '%')
  order by c.created_at desc
  limit 500;
$$;

drop function public.update_my_customer_settings(uuid, integer, boolean, time, text, integer, integer, integer, text, text, text, text, integer);
create or replace function public.update_my_customer_settings(
  p_customer_id uuid,
  p_daily_consumption integer default null,
  p_auto_consumption_enabled boolean default null,
  p_auto_consumption_time time default null,
  p_timezone text default null,
  p_low_stock_threshold integer default null,
  p_critical_threshold integer default null,
  p_safety_stock integer default null,
  p_delivery_instructions text default null,
  p_address text default null,
  p_phone text default null,
  p_household_type text default null,
  p_members_count integer default null,
  p_branch_name text default null
) returns public.customers
language plpgsql security definer set search_path = public as $$
declare
  c public.customers := public.customer_for_actor(p_customer_id, false);
begin
  if p_timezone is not null and not exists (select 1 from pg_timezone_names where name = p_timezone) then
    raise exception 'Unknown timezone %', p_timezone using errcode = '22023';
  end if;
  update public.customers set
    daily_consumption = coalesce(p_daily_consumption, daily_consumption),
    auto_consumption_enabled = coalesce(p_auto_consumption_enabled, auto_consumption_enabled),
    auto_consumption_since = case
      when coalesce(p_auto_consumption_enabled, auto_consumption_enabled) and not auto_consumption_enabled
        then public.customer_local_date(id)
      when not coalesce(p_auto_consumption_enabled, auto_consumption_enabled) then null
      else auto_consumption_since end,
    auto_consumption_time = coalesce(p_auto_consumption_time, auto_consumption_time),
    timezone = coalesce(p_timezone, timezone),
    low_stock_threshold = coalesce(p_low_stock_threshold, low_stock_threshold),
    critical_threshold = coalesce(p_critical_threshold, critical_threshold),
    safety_stock = coalesce(p_safety_stock, safety_stock),
    delivery_instructions = coalesce(nullif(trim(p_delivery_instructions), ''), delivery_instructions),
    address = coalesce(nullif(trim(p_address), ''), address),
    phone = coalesce(nullif(trim(p_phone), ''), phone),
    household_type = coalesce(p_household_type, household_type),
    members_count = coalesce(p_members_count, members_count),
    branch_name = coalesce(nullif(trim(p_branch_name), ''), branch_name)
  where id = c.id
  returning * into c;
  perform public.evaluate_stock_alert(c.id);
  perform public.refresh_prediction(c.id);
  return c;
end $$;

-- ---------------------------------------------------------------------
-- Customer accounts & members
-- ---------------------------------------------------------------------
create or replace function public.create_customer_account(p_name text, p_type public.customer_account_type)
returns public.customer_accounts
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := public.require_auth();
  a public.customer_accounts;
begin
  if (select role from public.profiles where id = v_uid) <> 'customer' then
    raise exception 'Only customer accounts can create a home, store or company' using errcode = '42501';
  end if;
  if (select count(*) from public.customer_accounts where owner_id = v_uid) >= 10 then
    raise exception 'You already own 10 accounts' using errcode = '22023';
  end if;
  insert into public.customer_accounts (name, account_type, owner_id)
  values (trim(p_name), coalesce(p_type, 'home'), v_uid) returning * into a;
  insert into public.customer_account_members (account_id, user_id, role) values (a.id, v_uid, 'owner');
  perform public.write_audit('account.created', 'customer_account', a.id, null, jsonb_build_object('type', a.account_type));
  return a;
end $$;

create or replace function public.update_customer_account(p_account_id uuid, p_name text default null,
                                                          p_type public.customer_account_type default null)
returns public.customer_accounts
language plpgsql security definer set search_path = public as $$
declare a public.customer_accounts;
begin
  perform public.require_account_admin(p_account_id);
  update public.customer_accounts set name = coalesce(nullif(trim(p_name), ''), name), account_type = coalesce(p_type, account_type)
  where id = p_account_id returning * into a;
  return a;
end $$;

create or replace function public.create_member_invite(p_account_id uuid, p_role public.account_member_role,
                                                       p_all_branches boolean default true, p_branch_ids uuid[] default '{}',
                                                       p_label text default null)
returns public.customer_member_invites
language plpgsql security definer set search_path = public as $$
declare
  v_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_code text;
  i int;
  r public.customer_member_invites;
begin
  perform public.require_account_admin(p_account_id);
  if p_role = 'owner' then
    raise exception 'There is only one owner' using errcode = '22023';
  end if;
  if p_role = 'admin' and public.my_account_role(p_account_id) <> 'owner' then
    raise exception 'Only the owner can add admins' using errcode = '42501';
  end if;
  if not coalesce(p_all_branches, true) and (
       coalesce(array_length(p_branch_ids, 1), 0) = 0
       or exists (select 1 from unnest(p_branch_ids) b where b not in (select id from public.customers where account_id = p_account_id))) then
    raise exception 'Choose at least one branch of this account' using errcode = '22023';
  end if;
  loop
    v_code := '';
    for i in 1..8 loop
      v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from public.customer_member_invites where code = v_code)
          and not exists (select 1 from public.staff_invites where code = v_code);
  end loop;
  insert into public.customer_member_invites (account_id, code, role, all_branches, branch_ids, label, created_by)
  values (p_account_id, v_code, p_role, coalesce(p_all_branches, true), coalesce(p_branch_ids, '{}'),
          nullif(trim(coalesce(p_label, '')), ''), auth.uid())
  returning * into r;
  return r;
end $$;

create or replace function public.join_customer_account(p_code text)
returns public.customer_account_members
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := public.require_auth();
  v_inv public.customer_member_invites;
  a public.customer_accounts;
  m public.customer_account_members;
  b uuid;
begin
  if (select role from public.profiles where id = v_uid) <> 'customer' then
    raise exception 'Family / team codes are for accounts registered as "I need water"' using errcode = '42501';
  end if;
  select * into v_inv from public.customer_member_invites where code = upper(trim(p_code)) for update;
  if v_inv.id is null or v_inv.revoked_at is not null or v_inv.used_at is not null or v_inv.expires_at <= now() then
    raise exception 'This code is invalid, used or expired. Ask the account owner for a new one.' using errcode = '22023';
  end if;
  if exists (select 1 from public.customer_account_members where account_id = v_inv.account_id and user_id = v_uid) then
    raise exception 'You are already a member of this account' using errcode = '23505';
  end if;
  insert into public.customer_account_members (account_id, user_id, role, all_branches)
  values (v_inv.account_id, v_uid, v_inv.role, v_inv.all_branches) returning * into m;
  foreach b in array v_inv.branch_ids loop
    insert into public.customer_member_branches (member_id, customer_id) values (m.id, b) on conflict do nothing;
  end loop;
  update public.customer_member_invites set used_by = v_uid, used_at = now() where id = v_inv.id;
  select * into a from public.customer_accounts where id = v_inv.account_id;
  perform public.notify(a.owner_id, 'account', 'info', 'New member joined',
    format('%s joined %s as %s.', coalesce(nullif((select full_name from public.profiles where id = v_uid), ''), 'Someone'),
           a.name, m.role), '/app/team', jsonb_build_object('member_id', m.id));
  perform public.write_audit('account.member_joined', 'customer_account', a.id, null, jsonb_build_object('role', m.role));
  return m;
end $$;

create or replace function public.list_account_members(p_account_id uuid)
returns table (id uuid, user_id uuid, full_name text, email text, phone text, role public.account_member_role,
               status text, all_branches boolean, branch_ids uuid[], created_at timestamptz)
language sql stable security definer set search_path = public as $$
  select m.id, m.user_id, p.full_name, p.email, p.phone, m.role, m.status, m.all_branches,
         coalesce((select array_agg(b.customer_id) from public.customer_member_branches b where b.member_id = m.id), '{}'),
         m.created_at
  from public.customer_account_members m join public.profiles p on p.id = m.user_id
  where m.account_id = p_account_id and p_account_id in (select public.my_account_ids())
  order by case m.role when 'owner' then 0 when 'admin' then 1 else 2 end, m.created_at;
$$;

create or replace function public.update_account_member(p_member_id uuid, p_role public.account_member_role default null,
                                                        p_status text default null, p_all_branches boolean default null,
                                                        p_branch_ids uuid[] default null)
returns public.customer_account_members
language plpgsql security definer set search_path = public as $$
declare
  m public.customer_account_members;
  v_me text;
  b uuid;
begin
  select * into m from public.customer_account_members where id = p_member_id for update;
  if m.id is null then
    raise exception 'Member not found' using errcode = 'P0002';
  end if;
  perform public.require_account_admin(m.account_id);
  v_me := public.my_account_role(m.account_id);
  if m.role = 'owner' then
    raise exception 'The owner cannot be changed or blocked' using errcode = '42501';
  end if;
  if v_me = 'admin' and (m.role = 'admin' or p_role = 'admin') then
    raise exception 'Only the owner can manage admins' using errcode = '42501';
  end if;
  if p_role = 'owner' then
    raise exception 'There is only one owner' using errcode = '22023';
  end if;
  if p_status is not null and p_status not in ('active', 'blocked') then
    raise exception 'Status must be active or blocked' using errcode = '22023';
  end if;
  update public.customer_account_members set
    role = coalesce(p_role, role), status = coalesce(p_status, status),
    all_branches = coalesce(p_all_branches, all_branches),
    blocked_at = case when p_status = 'blocked' then now() when p_status = 'active' then null else blocked_at end
  where id = m.id returning * into m;
  if p_branch_ids is not null then
    delete from public.customer_member_branches where member_id = m.id;
    foreach b in array p_branch_ids loop
      if b in (select id from public.customers where account_id = m.account_id) then
        insert into public.customer_member_branches (member_id, customer_id) values (m.id, b);
      end if;
    end loop;
  end if;
  if p_status is not null then
    perform public.notify(m.user_id, 'account', case when p_status = 'blocked' then 'critical' else 'success' end,
      case when p_status = 'blocked' then 'Your access was blocked' else 'Your access was restored' end,
      case when p_status = 'blocked' then 'The account owner blocked your access.' else 'You can use the account again.' end,
      '/home', '{}'::jsonb);
  end if;
  perform public.write_audit('account.member_updated', 'customer_account', m.account_id, null,
    jsonb_build_object('member_id', m.id, 'role', m.role, 'status', m.status));
  return m;
end $$;

create or replace function public.remove_account_member(p_member_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare m public.customer_account_members;
begin
  select * into m from public.customer_account_members where id = p_member_id;
  if m.id is null then
    raise exception 'Member not found' using errcode = 'P0002';
  end if;
  if m.user_id = auth.uid() and m.role <> 'owner' then
    delete from public.customer_account_members where id = m.id;  -- leaving an account yourself
    return;
  end if;
  perform public.require_account_admin(m.account_id);
  if m.role = 'owner' then
    raise exception 'The owner cannot be removed' using errcode = '42501';
  end if;
  if m.role = 'admin' and public.my_account_role(m.account_id) <> 'owner' then
    raise exception 'Only the owner can remove admins' using errcode = '42501';
  end if;
  delete from public.customer_account_members where id = m.id;
  perform public.write_audit('account.member_removed', 'customer_account', m.account_id, null, jsonb_build_object('member_id', m.id));
end $$;

create or replace function public.revoke_member_invite(p_invite_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_account uuid;
begin
  select account_id into v_account from public.customer_member_invites where id = p_invite_id;
  perform public.require_account_admin(v_account);
  update public.customer_member_invites set revoked_at = now() where id = p_invite_id and used_at is null;
end $$;

-- ---------------------------------------------------------------------
-- Supplier search + connection requests (supplier approves)
-- ---------------------------------------------------------------------
create or replace function public.search_suppliers(p_query text default null)
returns table (supplier_id uuid, business_name text, delivery_area text, address text, logo_url text)
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.require_auth();
  return query
  select s.id, s.business_name, s.delivery_area, s.address, s.logo_url
  from public.suppliers s
  where s.status = 'active' and s.listed
    and (coalesce(trim(p_query), '') = ''
         or s.business_name ilike '%' || trim(p_query) || '%'
         or s.delivery_area ilike '%' || trim(p_query) || '%'
         or s.address ilike '%' || trim(p_query) || '%')
  order by s.business_name
  limit 30;
end $$;

create or replace function public.request_supplier_connection(
  p_account_id uuid, p_supplier_id uuid, p_contact_name text, p_phone text, p_address text,
  p_branch_name text default null, p_delivery_instructions text default null, p_household_type text default null,
  p_members_count integer default null, p_opening_stock integer default null, p_daily_consumption integer default 0
) returns public.supplier_connection_requests
language plpgsql security definer set search_path = public as $$
declare
  r public.supplier_connection_requests;
  s public.suppliers;
  a public.customer_accounts;
begin
  perform public.require_account_admin(p_account_id);
  select * into s from public.suppliers where id = p_supplier_id;
  if s.id is null or s.status <> 'active' or not s.listed then
    raise exception 'This supplier is not accepting requests' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.customers where account_id = p_account_id and supplier_id = p_supplier_id
             and lower(address) = lower(trim(p_address))) then
    raise exception 'This address is already connected to this supplier' using errcode = '23505';
  end if;
  if exists (select 1 from public.supplier_connection_requests where account_id = p_account_id
             and supplier_id = p_supplier_id and lower(address) = lower(trim(p_address)) and status = 'pending') then
    raise exception 'A request for this address is already waiting for the supplier' using errcode = '23505';
  end if;
  select * into a from public.customer_accounts where id = p_account_id;
  insert into public.supplier_connection_requests (account_id, supplier_id, branch_name, contact_name, phone, address,
    delivery_instructions, household_type, members_count, opening_stock, daily_consumption, requested_by)
  values (p_account_id, p_supplier_id, nullif(trim(coalesce(p_branch_name, '')), ''), trim(p_contact_name),
          nullif(trim(coalesce(p_phone, '')), ''), trim(p_address), nullif(trim(coalesce(p_delivery_instructions, '')), ''),
          p_household_type, p_members_count, p_opening_stock, coalesce(p_daily_consumption, 0), auth.uid())
  returning * into r;
  perform public.notify(s.owner_id, 'account', 'warning', 'New customer request',
    format('%s (%s) wants water delivery at %s.', a.name, a.account_type, r.address),
    '/supplier/customers?tab=requests', jsonb_build_object('request_id', r.id));
  return r;
end $$;

create or replace function public.cancel_connection_request(p_request_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare r public.supplier_connection_requests;
begin
  select * into r from public.supplier_connection_requests where id = p_request_id for update;
  if r.id is null then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  perform public.require_account_admin(r.account_id);
  if r.status <> 'pending' then
    raise exception 'Request already %', r.status using errcode = '22023';
  end if;
  update public.supplier_connection_requests set status = 'cancelled', decided_at = now() where id = r.id;
end $$;

create or replace function public.decide_connection_request(p_request_id uuid, p_approve boolean, p_reason text default null)
returns public.supplier_connection_requests
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_active_supplier();
  r public.supplier_connection_requests;
  c public.customers;
  a public.customer_accounts;
  m record;
begin
  select * into r from public.supplier_connection_requests where id = p_request_id and supplier_id = v_sid for update;
  if r.id is null then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if r.status <> 'pending' then
    raise exception 'Request already %', r.status using errcode = '23505';
  end if;
  if not p_approve and (p_reason is null or char_length(trim(p_reason)) < 3) then
    raise exception 'Please give a reason (shown to the customer)' using errcode = '22023';
  end if;
  if p_approve then
    c := public.create_branch(r.account_id, r.supplier_id, r.branch_name, r.contact_name, r.phone, r.address,
                              r.delivery_instructions, r.household_type, r.members_count, r.opening_stock,
                              r.daily_consumption, r.requested_by);
  end if;
  update public.supplier_connection_requests set
    status = case when p_approve then 'approved' else 'rejected' end, reason = nullif(trim(coalesce(p_reason, '')), ''),
    customer_id = c.id, decided_by = auth.uid(), decided_at = now()
  where id = r.id returning * into r;
  select * into a from public.customer_accounts where id = r.account_id;
  for m in select user_id from public.customer_account_members
           where account_id = r.account_id and status = 'active' and role in ('owner', 'admin') loop
    perform public.notify(m.user_id, 'account', case when p_approve then 'success' else 'warning' end,
      case when p_approve then 'Supplier accepted your request' else 'Supplier declined your request' end,
      case when p_approve then format('%s will now deliver to %s.', (select business_name from public.suppliers where id = v_sid), r.address)
           else format('%s could not accept the request for %s: %s', (select business_name from public.suppliers where id = v_sid),
                       r.address, r.reason) end,
      '/app/branches', jsonb_build_object('request_id', r.id));
  end loop;
  perform public.write_audit(case when p_approve then 'customer.request_approved' else 'customer.request_rejected' end,
                             'supplier_connection_request', r.id, v_sid, jsonb_build_object('reason', r.reason));
  return r;
end $$;

-- Code / QR / invite link: instant connection (no approval).
-- Older app versions call this without p_account_id: an account is created
-- (or reused) for them so they keep working.
drop function public.connect_to_supplier(text, text, text, text, text, text, integer, integer, text, integer);
create or replace function public.connect_to_supplier(
  p_customer_name text,
  p_phone text,
  p_address text,
  p_delivery_instructions text default null,
  p_business_code text default null,
  p_invite_token text default null,
  p_opening_stock integer default null,
  p_daily_consumption integer default 0,
  p_household_type text default null,
  p_members_count integer default null,
  p_account_id uuid default null,
  p_branch_name text default null
) returns public.customers
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := public.require_auth();
  v_supplier public.suppliers;
  v_invite public.supplier_invites;
  v_account uuid := p_account_id;
  c public.customers;
begin
  if (select role from public.profiles where id = v_uid) <> 'customer' then
    raise exception 'Only customer accounts can connect to a supplier' using errcode = '42501';
  end if;
  if p_invite_token is not null then
    select * into v_invite from public.supplier_invites where token = p_invite_token for update;
    if v_invite.id is null or v_invite.revoked_at is not null
       or (v_invite.expires_at is not null and v_invite.expires_at <= now())
       or (v_invite.max_uses is not null and v_invite.uses >= v_invite.max_uses) then
      raise exception 'This invitation link is invalid or has expired' using errcode = '22023';
    end if;
    select * into v_supplier from public.suppliers where id = v_invite.supplier_id;
  elsif p_business_code is not null then
    select * into v_supplier from public.suppliers where business_code = upper(trim(p_business_code));
  else
    raise exception 'A supplier code or invitation link is required' using errcode = '22023';
  end if;
  if v_supplier.id is null or v_supplier.status <> 'active' then
    raise exception 'Supplier not found or not accepting customers' using errcode = 'P0002';
  end if;

  if v_account is null then
    select id into v_account from public.customer_accounts where owner_id = v_uid order by created_at limit 1;
    if v_account is null then
      v_account := (public.create_customer_account(p_customer_name,
        case p_household_type when 'shop' then 'store'::public.customer_account_type
                              when 'office' then 'company'::public.customer_account_type
                              else 'home'::public.customer_account_type end)).id;
    end if;
  else
    perform public.require_account_admin(v_account);
  end if;

  c := public.create_branch(v_account, v_supplier.id, p_branch_name, p_customer_name, p_phone, p_address,
                            p_delivery_instructions, p_household_type, p_members_count, p_opening_stock,
                            p_daily_consumption, v_uid);
  if v_invite.id is not null then
    update public.supplier_invites set uses = uses + 1 where id = v_invite.id;
  end if;
  update public.profiles set full_name = coalesce(nullif(full_name, ''), trim(p_customer_name)),
                             phone = coalesce(phone, nullif(trim(coalesce(p_phone, '')), ''))
   where id = v_uid;
  return c;
end $$;

-- ---------------------------------------------------------------------
-- Function privileges
-- ---------------------------------------------------------------------
do $$
declare f text;
begin
  foreach f in array array[
    'public.my_customer_ids()', 'public.my_billing_customer_ids()', 'public.my_account_ids()',
    'public.my_account_role(uuid)',
    'public.create_customer_account(text, public.customer_account_type)',
    'public.update_customer_account(uuid, text, public.customer_account_type)',
    'public.create_member_invite(uuid, public.account_member_role, boolean, uuid[], text)',
    'public.join_customer_account(text)', 'public.list_account_members(uuid)',
    'public.update_account_member(uuid, public.account_member_role, text, boolean, uuid[])',
    'public.remove_account_member(uuid)', 'public.revoke_member_invite(uuid)',
    'public.search_suppliers(text)',
    'public.request_supplier_connection(uuid, uuid, text, text, text, text, text, text, integer, integer, integer)',
    'public.cancel_connection_request(uuid)', 'public.decide_connection_request(uuid, boolean, text)',
    'public.connect_to_supplier(text, text, text, text, text, text, integer, integer, text, integer, uuid, text)',
    'public.update_my_customer_settings(uuid, integer, boolean, time, text, integer, integer, integer, text, text, text, text, integer, text)',
    'public.list_supplier_customers()', 'public.admin_list_customers(text)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated, service_role', f);
  end loop;
  foreach f in array array[
    'public.head_customer_id(uuid)', 'public.billing_group(uuid)', 'public.require_account_admin(uuid)',
    'public.customer_for_billing(uuid)',
    'public.notify_customer(uuid, text, text, text, text, text, text, jsonb, text)',
    'public.create_branch(uuid, uuid, text, text, text, text, text, text, integer, integer, integer, uuid)',
    'public.customer_for_actor(uuid, boolean)'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end $$;

-- Realtime: requests appear live for suppliers.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    execute 'alter publication supabase_realtime add table public.supplier_connection_requests';
  end if;
end $$;
